import SwiftUI

struct APIConflictReview:View {
    @ObservedObject var store:APIStore
    let operation:APIMutation
    @Environment(\.dismiss) private var dismiss
    @State private var remote:APIValue = .null
    @State private var version:APIValue = .null
    @State private var selected=Set<String>()
    @State private var problem:String?
    @State private var confirm=false
    var local:APIValue{operation.path.hasSuffix("/service") ? operation.body?["report"] ?? .null : operation.body ?? .null}
    var keys:[String]{Set(local.object.keys).union(remote.object.keys).subtracting(["id","version","mutationId","operationId","createdAt","updatedAt","createdBy","updatedBy"]).sorted()}
    var body:some View{List{Text("Serverový záznam má novější verzi. Vyberte pouze údaje, které chcete převzít z tohoto iPhonu. Ostatní zůstanou podle serveru.").font(.callout);ForEach(keys,id:\.self){key in DisclosureGroup(key){Text("Na serveru").font(.caption.bold());Text(display(remote[key])).font(.footnote);Text("V iPhonu").font(.caption.bold());Text(display(local[key])).font(.footnote);Toggle("Použít hodnotu z iPhonu",isOn:Binding(get:{selected.contains(key)},set:{on in if on{selected.insert(key)}else{selected.remove(key)}}))}};if let problem{Text(problem).foregroundStyle(DiaryStyle.warning)};Button("Potvrdit sloučení a znovu odeslat"){confirm=true}.disabled(version.isNull || !store.online)}.navigationTitle("Kontrola konfliktu").task{await load()}.confirmationDialog("Nahradit odmítnutý zápis zkontrolovanou změnou?",isPresented:$confirm,titleVisibility:.visible){Button("Odeslat vybrané údaje"){Task{await save()}};Button("Zrušit",role:.cancel){}}}
    func display(_ value:APIValue)->String{if value.isNull{return "Nevyplněno"};if value.object.isEmpty && value.array.isEmpty{return value.string};return String(data:(try? value.data()) ?? Data(),encoding:.utf8) ?? ""}
    func load()async{do{let result:APIValue;if operation.path.contains("/services/"){let path=operation.path.split(separator:"/").dropLast().joined(separator:"/");let response=try await store.get("/"+path);result=response["services"].array.first{$0.id==operation.path.split(separator:"/").last.map(String.init)} ?? .null;remote=result;version=result["version"]}else{result=try await store.get(operation.path);if operation.path.hasSuffix("/service"){remote=result["report"];version=result["job"]["version"]}else{remote=result["defect"].isNull ? result : result["defect"];version=remote["version"]}}}catch{problem=error.localizedDescription}}
    func save()async{guard operation.state=="conflict",let vault=store.vault,operation.scope==store.scope,!version.isNull else{return};do{var merged=remote;for key in selected{merged[key]=local[key]};var body=operation.body ?? .object([:]);let id=UUID().uuidString;body["version"]=version;if operation.path.hasSuffix("/service"){body["report"]=merged;body["operationId"] = .s(id)}else{for key in local.object.keys where !["version","mutationId"].contains(key){body[key]=merged[key]};body["mutationId"] = .s(id)};var replacement=APIMutation(id:id,path:operation.path,method:operation.method,body:body,bytes:nil,contentType:operation.contentType,headers:operation.headers,scope:operation.scope,dependsOn:operation.dependsOn,draftKey:operation.draftKey);replacement.draftSnapshot=body;guard let index=vault.state.outbox.firstIndex(where:{$0.id==operation.id})else{throw APIError.local("Zápis se mezitím změnil.")};vault.state.outbox[index]=replacement;if let key=operation.draftKey{var draft=store.draft(key,fallback:body);draft.value=body;draft.operationID=id;vault.state.drafts[key]=draft};try vault.persist();store.updateOutbox();await store.sync();dismiss()}catch{problem=error.localizedDescription}}
}
